          "detail": "正月改元证圣；薛怀义失宠愤而纵火焚天堂延及明堂，二月甲子武曌命太平公主设伏缚杀怀义，复命重造明堂。四月武三思率四夷君长铸铜铁“大周万国颂德天枢”立于端门外，高百五尺，刻百官及蕃王名氏。五月，游学南海天竺二十五年的高僧义净携梵本经律论近四百部、合五十万颂返抵神都洛阳，武曌亲率百官出上东门迎劳。九月改元天册万岁；腊月（十二月）甲申，武曌亲登中岳嵩山行封禅大礼，改元万岁登封。",
