          "detail": "五月，陇右节度使哥舒翰进击吐蕃，尽复金城公主和亲后沦入吐蕃的黄河九曲肥沃牧地，置神策军及洮阳、浇河二郡，唐对吐蕃军事态势达于极盛。十月，双目失明的六十六岁律宗大师鉴真率弟子法进、思托等，秘密搭乘日本第十次遣唐副使大伴古麻吕归国船自苏州常熟黄泗浦第六次启航，冲破风涛于十二月二十日抵达日本萨摩国秋妻屋浦，翌年入平城京于东大寺筑坛为圣武太上皇、光明皇太后、孝谦天皇授戒，开创日本律宗与汉方医药、唐招提寺建筑规范。",
