          "detail": "正月乙卯朔，安禄山于洛阳自称大燕皇帝，改元圣武；常山城陷，颜杲卿骂贼钩舌殉国；郭子仪、李光弼率朔方河东兵出井陉，五月于嘉山大破史思明，复河北十余郡。六月杨国忠惧哥舒翰图己，连遣使逼翰出潼关复陕洛；辛卯翰抚膺恸哭引兵出关，于灵宝西原隘道中崔乾祐伏击，二十万唐军溃散，哥舒翰为部将火拔归仁执降安禄山，潼关失守。甲午黎明玄宗弃长安西奔入蜀（乙酉叛军陷长安），丙申行次马嵬驿，随驾龙武大将军陈玄礼率禁军哗变斩右相杨国忠及韩国、秦国夫人，围驿请诛贵妃，玄宗不得已命高力士引杨贵妃缢于佛堂。父老遮道留皇太子李亨讨贼，李亨率数千骑北趋朔方，七月甲子于灵武南门楼即皇帝位（唐肃宗），遥尊玄宗为上皇天帝，改元至德元载。",
