          "detail": "正月乙卯夜，久病失明暴虐欲易储之安禄山，为其子安庆绪与谋主严庄、阉竖李猪儿潜入洛阳寝帐持刀斫腹弑杀，庆绪袭称燕帝；同时李光弼以不足万兵坚守太原大破史思明十万攻城军。自春至十月，真源令张巡与睢阳太守许远合兵六千八百人死守运河咽喉睢阳城，与尹子奇十三万燕军大小四百余战、斩将三百、杀卒十余万，城中食尽掘鼠罗雀及皮铠，十月癸丑城陷，张巡、南霁云、雷万春等三十六将宁死不屈殉国（许远押洛阳遇害），全保江淮财赋半壁。九月广平王李俶（代宗）为元帅、郭子仪为副元帅，统朔方安西兵十五万及回纥叶护精骑四千，于长安城南香积寺血战斩燕军六万（李嗣业赤膊持长刀堵阵），癸卯收复长安；十月壬戌乘胜复东都洛阳，安庆绪走保相州邺城；十二月上皇玄宗自蜀返归长安。",
