          "detail": "七月改元广德。安史乱中河西陇右精锐尽调内地勤王，吐蕃赞普赤松德赞乘虚鲸吞兰、廓、河、鄯、洮、岷、秦、成、渭数十州；十月吐蕃大相马重英（达扎路恭）率吐蕃、吐谷浑、党项二十万众度便桥直扑京师（程元振前蔽塞军情不报），丙子代宗仓皇出奔陕州，戊寅吐蕃入占长安十五日（逻些今存《唐蕃恩兰·达扎路恭纪功碑》与唐史互证），立邠王守礼孙广武王李承宏为帝。诏急拜郭子仪为关内副元帅，子仪仅有数十骑，至商州收散卒四千，命王甫入长安城中夜击鼓欢呼、自于南山张旗帜设疑兵，吐蕃惧而悉众西退，子仪不血刃光复长安。同年刘晏领度支盐铁转运使，疏浚汴水，创江淮至渭口官船“纲运”分段雇佣法及就场专卖巡院信息网，挽救中唐财政命脉。",
