          "detail": "正月辛未朔改元建中。鉴于安史乱后版籍隳坏、均田瓦解、租庸调名存实亡而地方苛敛百出，德宗采纳宰相杨炎奏议颁行“两税法”：凡百役之费一钱之敛，先度其数而赋于人（量出以制入）；户无主客，以见居为簿；人无丁中，以贫富为差；不居处而行商者，在所州县税三十之一；并省租庸杂徭不复别征，分夏税（无过六月）、秋税（无过十一月）两季输纳。此法奠定唐宋明清土地资产税基本范式。同年七月，杨炎挟私怨诬构前度支理财功臣刘晏于忠州赐死，天下冤之。",
