          "detail": "正月丁亥，宪宗遣中使自凤翔法门寺迎佛指骨入大内留奉三日，王公士民瞻施若狂；刑部侍郎韩愈抗疏上《论佛骨表》力陈梁武帝事佛亡国之鉴，请将佛骨投诸水火，宪宗大怒欲抵死，裴度、崔群力救乃贬韩愈为潮州刺史（愈至潮州兴乡校延赵德、祭鳄鱼）。二月戊戌，田弘正、李愬连破淄青军，李师道猜忌大将刘悟（刘正臣孙），刘悟于阳谷引兵夜回袭破郓州牙城，斩李师道父子首级献田弘正，割据山东五十四年的淄青李氏覆灭；诏分其十二州为淄青平卢、天平（郓曹濮）、兖海三节度，至此天下藩镇悉遵朝命，史称“元和中兴”。十月柳宗元卒于柳州（年四十七）。同年渤海宣王大仁秀即位改元建兴，南定新罗北境、北拓黑水诸部，建五京十五府六十二州，时称“海东盛国”。",
