          "detail": "正月，浙东起义首领裘甫据剡县，众逾三万，从刘畦议自称天下都知兵马使，改元“罗平”，铸“天平胜宝”印，分兵连破唐兴、上虞、余姚，震动东南；三月朝廷调前安南都护王式为浙东观察使，发忠武、义成、淮南诸道军及吐蕃、回鹘配隶骑兵水陆并进，六月攻破剡县生擒裘甫，八月斩于长安东市，揭开晚唐大规模农民战争序幕。十一月丁丑大赦改元咸通；十二月大礼（南诏）诱群蛮攻陷交趾，安南都护李鄠奔武州。",
