          "detail": "陈州赵犨被围近三百日，与朱全忠卑辞求救于河东李克用；四月克用率五万番汉军南下连破黄巢于太康、西华，解陈州之围，五月追至中牟王满渡乘半渡击溃齐军，尚让率万余人降、霍存葛从周等归朱全忠。克用旋师过汴州，朱全忠迎入城中上源驿设宴款待；是夜甲辰，全忠忌克用骁悍且愤其酒后骄语，发兵围上源驿纵火鼓噪掩杀，亲随三百余人皆死，侍者郭景铢灭烛藏克用于床下以水沃面苏醒，适天大雷雨，薛志勤扶克用乘闪电缒尉氏门突围归营，自此朱、李两镇血海深仇不共戴天。六月丙午，黄巢残部走入泰山东南莱芜狼虎谷，为外甥林言斩首（《新唐书》载巢自刎嘱甥献首全宗族）降于时溥，历时十载席卷十二道的黄巢大起义终告覆灭。",
